package com.example.starter.domain;

/**
 * 垃圾品类：可回收物、厨余垃圾、有害垃圾、其他垃圾。
 */
public enum WasteCategory {
    RECYCLABLE,
    KITCHEN,
    HAZARDOUS,
    OTHER
}

package com.example.starter.domain;

/**
 * 收运联单状态机：执行中 -> 已回执 / 异常待核查 -> 核查闭环。
 */
public enum ManifestStatus {
    /** 已登记进场称重，尚未到达处理设施回执。 */
    IN_TRANSIT,
    /** 回执净重偏差在 2%（含）以内，正常闭环。 */
    RECEIVED,
    /** 回执净重偏差超过 2%，转入异常核查。 */
    EXCEPTION,
    /** 异常核查已给出结论（设备误差或装载差异），留痕闭环。 */
    RESOLVED
}

package com.example.starter.domain;

/**
 * 异常核查结论分类。
 */
public enum ReviewConclusion {
    /** 设备误差：称重计量设备导致的偏差。 */
    DEVICE_ERROR,
    /** 装载差异：运输过程装载变化导致的偏差。 */
    LOADING_DIFF
}

package com.example.starter.support;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带稳定错误码与 HTTP 状态，由全局异常处理器转换为响应体。
 */
public class BizException extends RuntimeException {

    private final String code;
    private final HttpStatus status;

    public BizException(String code, HttpStatus status, String message) {
        super(message);
        this.code = code;
        this.status = status;
    }

    public String getCode() {
        return code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public static BizException badRequest(String code, String message) {
        return new BizException(code, HttpStatus.BAD_REQUEST, message);
    }

    public static BizException notFound(String code, String message) {
        return new BizException(code, HttpStatus.NOT_FOUND, message);
    }

    public static BizException conflict(String code, String message) {
        return new BizException(code, HttpStatus.CONFLICT, message);
    }
}

package com.example.starter.support;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.StringJoiner;

/**
 * 幂等指纹：对 requestId 与全部业务字段做规范化拼接后的 SHA-256。
 * 同键同参指纹一致返回首次结果，同键异参指纹不同返回 409。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 计算指纹。字段按调用方给定顺序以竖线拼接，null 规范化为空串。
     */
    public static String of(String... fields) {
        StringJoiner joiner = new StringJoiner("|");
        for (String field : fields) {
            joiner.add(field == null ? "" : field);
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(joiner.toString().getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }
}

package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：业务时间统一取自 Clock，便于测试用可控时钟覆盖。
 */
@Configuration
public class TimeConfig {

    @Bean
    public Clock businessClock() {
        return Clock.systemUTC();
    }
}

